/* ===== NOKIA N82 CURSOR =====
   Replaces the ring cursor with a spinning Nokia N82 rendered through the same
   pipeline as the tape models: white metal MeshStandardMaterial + studio env-map,
   one directional light, then luma two-tone + bloom/star-streak post passes. */
(function(){
  if (window.__IS_PHONE || !window.THREE || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
  var MODEL = "";
  var ENV   = "data:image/jpeg;base64,";

  /* ---- geometry (quantized int16 positions + uint16 indices) ---- */
  function decode(b64){
    var bin = atob(b64), n = bin.length, u8 = new Uint8Array(n);
    for (var i = 0; i < n; i++) u8[i] = bin.charCodeAt(i);
    var dv = new DataView(u8.buffer), nv = dv.getUint32(0, true), ni = dv.getUint32(4, true);
    var q = new Int16Array(u8.buffer, 8, nv * 3), pos = new Float32Array(nv * 3);
    for (var j = 0; j < nv * 3; j++) pos[j] = q[j] / 32767;
    var idx = new Uint16Array(u8.buffer.slice(8 + nv * 6, 8 + nv * 6 + ni * 2));
    var g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    g.setIndex(new THREE.BufferAttribute(idx, 1));
    g.computeVertexNormals();
    return g;
  }

  /* ---- DOM ---- */
  var css = document.createElement('style');
  css.textContent = 'html:not(.is-phone) body,html:not(.is-phone) body *{cursor:none!important}.cursor-dot{display:none!important}#nokia-cursor{position:fixed;left:0;top:0;pointer-events:none;z-index:9999;will-change:transform;opacity:0;transition:opacity .25s}';
  document.head.appendChild(css);
  var SIZE = 120;                                   // canvas box in CSS px
  var cv = document.createElement('canvas');
  cv.id = 'nokia-cursor';
  cv.style.width = cv.style.height = SIZE + 'px';
  document.body.appendChild(cv);

  /* ---- renderer / scene (matches tape renderer) ---- */
  var dpr = Math.min(window.devicePixelRatio || 1, 2);
  var renderer = new THREE.WebGLRenderer({ canvas: cv, alpha: true, antialias: true, premultipliedAlpha: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(dpr);
  renderer.setSize(SIZE, SIZE, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.setClearColor(0x000000, 0);
  var W = Math.round(SIZE * dpr), H = W;

  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(36, 1, 0.1, 100);
  camera.position.set(0, 0, 3.4);
  var sun = new THREE.DirectionalLight(0xffffff, 0.6);
  sun.position.set(0, 1, 0);
  scene.add(sun);

  var envTex = new THREE.TextureLoader().load(ENV, function(t){ t.mapping = THREE.EquirectangularReflectionMapping; t.encoding = THREE.sRGBEncoding; mat.envMap = t; mat.needsUpdate = true; });
  var mat = new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: 1, roughness: 0.1, transparent: true, side: THREE.DoubleSide });
  var mesh = new THREE.Mesh(decode(MODEL), mat);
  mesh.rotation.x = Math.PI / 2;                    // long axis Z -> upright (top up)
  var holder = new THREE.Object3D();
  holder.add(mesh);
  scene.add(holder);

  /* ---- post pipeline (same shaders as the tape) ---- */
  var rtOpts = { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, format: THREE.RGBAFormat };
  var rtScene = new THREE.WebGLRenderTarget(W, H, rtOpts); rtScene.texture.encoding = THREE.sRGBEncoding;
  var rtA = new THREE.WebGLRenderTarget(W >> 1, H >> 1, rtOpts);
  var rtB = new THREE.WebGLRenderTarget(W >> 1, H >> 1, rtOpts);
  var rtGlow = new THREE.WebGLRenderTarget(W >> 1, H >> 1, rtOpts);
  var VS = 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }';
  function pass(fs, uniforms){ return new THREE.ShaderMaterial({ vertexShader: VS, fragmentShader: fs, uniforms: uniforms, depthWrite: false, depthTest: false }); }
  var bright = pass(
    'precision highp float;varying vec2 vUv;uniform sampler2D uScene;' +
    'float luma(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }' +
    'void main(){ vec4 t = texture2D(uScene, vUv); float l = luma(t.rgb) * t.a; float w = smoothstep(0.58, 0.95, l); gl_FragColor = vec4(t.rgb * t.a * w, 1.0); }',
    { uScene: { value: rtScene.texture } });
  var blur = pass(
    'precision highp float;varying vec2 vUv;uniform sampler2D uSrc;uniform vec2 uDir;' +
    'void main(){ vec3 c = texture2D(uSrc, vUv).rgb * 0.2270;' +
    ' c += (texture2D(uSrc, vUv + uDir * 1.3846).rgb + texture2D(uSrc, vUv - uDir * 1.3846).rgb) * 0.3162;' +
    ' c += (texture2D(uSrc, vUv + uDir * 3.2308).rgb + texture2D(uSrc, vUv - uDir * 3.2308).rgb) * 0.0703;' +
    ' gl_FragColor = vec4(c, 1.0); }',
    { uSrc: { value: null }, uDir: { value: new THREE.Vector2() } });
  var star = pass(
    'precision highp float;varying vec2 vUv;uniform sampler2D uSrc;uniform vec2 uRes;uniform float uSpike;' +
    'void main(){ vec2 px = 1.0 / uRes; vec3 glow = texture2D(uSrc, vUv).rgb; vec3 star = vec3(0.0); float sp = 1.0 + uSpike * 1.5;' +
    ' for (int k = 1; k <= 12; k++) { float fk = float(k); float w = pow(0.78, fk);' +
    '  vec2 o = vec2(fk * 2.2 * sp, 0.0) * px; star += (texture2D(uSrc, vUv + o).rgb + texture2D(uSrc, vUv - o).rgb) * w;' +
    '  vec2 o2 = vec2(0.0, fk * 2.2 * sp) * px; star += (texture2D(uSrc, vUv + o2).rgb + texture2D(uSrc, vUv - o2).rgb) * w;' +
    '  vec2 o3 = vec2(fk * 1.6, fk * 1.6) * px * sp; star += (texture2D(uSrc, vUv + o3).rgb + texture2D(uSrc, vUv - o3).rgb) * w * 0.45;' +
    '  vec2 o4 = vec2(fk * 1.6, -fk * 1.6) * px * sp; star += (texture2D(uSrc, vUv + o4).rgb + texture2D(uSrc, vUv - o4).rgb) * w * 0.45; }' +
    ' gl_FragColor = vec4(glow * 0.55 + star * 0.07, 1.0); }',
    { uSrc: { value: rtB.texture }, uRes: { value: new THREE.Vector2(W >> 1, H >> 1) }, uSpike: { value: 0 } });
  var composite = pass(
    'precision highp float;varying vec2 vUv;uniform sampler2D uScene;uniform sampler2D uGlow;uniform float uSpike;' +
    'float luma(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }' +
    'void main(){ vec4 t = texture2D(uScene, vUv); float a = t.a;' +
    ' float l = luma(t.rgb); float tone = smoothstep(0.40, 0.50, l);' +
    ' vec3 sil = mix(vec3(0.0), vec3(0.96, 0.92, 1.0), tone);' +
    ' vec3 fx = texture2D(uGlow, vUv).rgb * vec3(0.86, 0.74, 1.0);' +
    ' fx += uSpike * 0.18 * vec3(0.9, 0.85, 1.0) * a;' +
    ' vec3 col = sil * a + fx;' +                      /* premultiplied: silhouette over page, glow additive */
    ' float fa = clamp(a + max(fx.r, max(fx.g, fx.b)), 0.0, 1.0);' +
    ' gl_FragColor = vec4(col, fa); }',
    { uScene: { value: rtScene.texture }, uGlow: { value: rtGlow.texture }, uSpike: { value: 0 } });
  var quadScene = new THREE.Scene();
  var quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), composite);
  quadScene.add(quad);
  var quadCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  function run(material, target){ quad.material = material; renderer.setRenderTarget(target); renderer.render(quadScene, quadCam); }

  /* ---- interaction ---- */
  var mx = -999, my = -999, cx = mx, cy = my, shown = false;
  var down = false, hover = false, spin = 0, speed = 0, BASE = 1.4, FAST = 11, scale = 1, spike = 0;
  var HOVER_SEL = 'a,button,[role=button],.poster-card,.tf-file,.cmdk-item,.tl-seg,.tl-nav,.win-act,input,textarea,select,label,summary';
  window.addEventListener('mousemove', function(e){ mx = e.clientX; my = e.clientY; if (!shown){ shown = true; cx = mx; cy = my; cv.style.opacity = '1'; } }, { passive: true });
  window.addEventListener('mousedown', function(){ down = true; spike = 1; });
  window.addEventListener('mouseup',   function(){ down = false; });
  window.addEventListener('blur',      function(){ down = false; });
  window.addEventListener('mouseover', function(e){ hover = !!(e.target && e.target.closest && e.target.closest(HOVER_SEL)); }, { passive: true });
  document.documentElement.addEventListener('mouseleave', function(){ cv.style.opacity = '0'; });
  document.documentElement.addEventListener('mouseenter', function(){ if (shown) cv.style.opacity = '1'; });

  var last = performance.now();
  (function loop(now){
    requestAnimationFrame(loop);
    var dt = Math.min((now - last) / 1000, 0.05); last = now;
    if (!shown) return;
    cx += (mx - cx) * 0.4; cy += (my - cy) * 0.4;
    var target = down ? FAST : BASE;
    speed += (target - speed) * (down ? 0.22 : 0.05);  // snap up on click, ease back after
    spin += speed * dt;
    spike += (0 - spike) * 0.08;
    scale += ((hover ? 1.3 : 1) - scale) * 0.15;
    cv.style.transform = 'translate(' + (cx - SIZE / 2).toFixed(1) + 'px,' + (cy - SIZE / 2).toFixed(1) + 'px)';
    holder.rotation.y = spin;
    holder.rotation.z = -0.28 + Math.sin(spin * 0.5) * 0.12;
    holder.rotation.x = 0.18;
    holder.scale.setScalar(0.95 * scale);

    renderer.setRenderTarget(rtScene); renderer.clear(); renderer.render(scene, camera);
    run(bright, rtA);
    blur.uniforms.uSrc.value = rtA.texture; blur.uniforms.uDir.value.set(1 / (W >> 1), 0); run(blur, rtB);
    blur.uniforms.uSrc.value = rtB.texture; blur.uniforms.uDir.value.set(0, 1 / (H >> 1)); run(blur, rtA);
    star.uniforms.uSrc.value = rtA.texture; star.uniforms.uSpike.value = spike; run(star, rtGlow);
    composite.uniforms.uSpike.value = spike; run(composite, null);
  })(last);
})();
